import{_ as t,a as o,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"List Inventory Sources","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"List Inventory Sources","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/inventory-sources?per_page=10\\" -H \\"Authorization: Bearer <token>\\"\\n","response":"{ \\"data\\": [{ \\"id\\": 1, \\"code\\": \\"default\\", \\"name\\": \\"Default Warehouse\\", \\"priority\\": 1, \\"status\\": 1, \\"country\\": \\"US\\", \\"city\\": \\"Springfield\\" }], \\"meta\\": { \\"currentPage\\": 1, \\"perPage\\": 10, \\"lastPage\\": 1, \\"total\\": 1, \\"from\\": 1, \\"to\\": 1 } }\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/settings/inventory-sources/list.md","filePath":"api/rest-api/admin/settings/inventory-sources/list.md","lastUpdated":1786429091000}'),r={name:"api/rest-api/admin/settings/inventory-sources/list.md"};function c(i,e,s,n,l,h){return a(),o("div",null,e[0]||(e[0]=[d('<h1 id="list-inventory-sources" tabindex="-1">List Inventory Sources <a class="header-anchor" href="#list-inventory-sources" aria-label="Permalink to &quot;List Inventory Sources&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/settings/inventory-sources</code></td><td>GET</td></tr></tbody></table><p>Returns every inventory source configured in the store in the <code>{ data, meta }</code> envelope. Every column is populated on each row, so you can read whatever you need without a follow-up call.</p><div class="tip custom-block"><p class="custom-block-title">How this menu works</p><p>For what an inventory source is, field meanings, and the delete guards, see the <a href="/api/rest-api/admin/settings/inventory-sources/list.html">Inventory Sources overview</a>.</p></div><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Page number, 1-based. Default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>Items per page. Default <code>10</code>, max <code>50</code>.</td></tr></tbody></table><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Query parameters that narrow the result. Supplying more than one <strong>narrows further</strong> — they combine with logical <strong>AND</strong>. They mirror the admin Inventory Sources datagrid filters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Match</th><th>Example</th></tr></thead><tbody><tr><td><code>code</code></td><td>Partial (contains).</td><td><code>?code=warehouse</code></td></tr><tr><td><code>name</code></td><td>Partial (contains).</td><td><code>?name=West</code></td></tr><tr><td><code>status</code></td><td>Exact — <code>0</code> (inactive) or <code>1</code> (active).</td><td><code>?status=1</code></td></tr><tr><td><code>country</code></td><td>Exact — 2-letter country code.</td><td><code>?country=US</code></td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>id</code> (default), <code>code</code>, <code>name</code>, <code>priority</code>, <code>status</code></td></tr><tr><td><code>order</code></td><td><code>asc</code>, <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><p>Both the compound form <code>?sort=name-asc</code> and the split form <code>?sort=name&amp;order=asc</code> are accepted.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>status</code> is <code>0</code> (inactive) or <code>1</code> (active); only active sources are available for fulfilment.</li><li><code>latitude</code> / <code>longitude</code> are <code>null</code> when the source has no geo-coordinates configured.</li><li>Seeded core sources (such as the <code>default</code> source) may have <code>null</code> <code>createdAt</code> / <code>updatedAt</code>.</li></ul><p>See the <a href="/api/rest-api/admin/settings/inventory-sources/list.html">Inventory Sources overview</a> for field meanings and behaviour.</p>',15)]))}const m=t(r,[["render",c]]);export{p as __pageData,m as default};
